    /// <summary>
    /// CB272 - for inserting records for FoodLiquor Invoice
    /// </summary>
    /// <param name = "_custInvoiceJour">_custInvoiceJour</param>
    /// <param name = "_custInvoiceTrans">_custInvoiceTrans</param>
    public void insertMETCTSalesInvoiceTmp(CustInvoiceJour _custInvoiceJour)
    {
        METCBCTInvoiceHeaderTable   metCBCTInvoiceHeaderTable;

        RecordInsertList recList = new RecordInsertList(tableNum(METSalesCTInvoiceTmp));

        while select metCBCTInvoiceHeaderTable
            where metCBCTInvoiceHeaderTable.RefSalesId == _custInvoiceJour.SalesId
        {
            metSalesCTInvoiceTmp.clear();

            metSalesCTInvoiceTmp.SupplierName           =   metCBCTInvoiceHeaderTable.getVendName(); //suplier name
            metSalesCTInvoiceTmp.VendorAccount          =   metCBCTInvoiceHeaderTable.VendorAccount; //suplier Id
            metSalesCTInvoiceTmp.TaxInvoiceNum          =   metCBCTInvoiceHeaderTable.TaxInvoiceNum;// supplier inv no
            metSalesCTInvoiceTmp.DocumentDate           =   metCBCTInvoiceHeaderTable.DocumentDate; //invoice date
            metSalesCTInvoiceTmp.VendInvoiceAmtInclGST  =   metCBCTInvoiceHeaderTable.VendInvoiceAmtInclGST;//incl GST
            metSalesCTInvoiceTmp.VendInvoiceGSTAmount   =   metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount; //GST
            metSalesCTInvoiceTmp.Number                 =   metCBCTInvoiceHeaderTable.Number;
            
            [metSalesCTInvoiceTmp.ProdCATDimensionValue, 
                metSalesCTInvoiceTmp.ProductCategoryName] = this.getProductCategory(metSalesCTInvoiceTmp.VendorAccount);

            metSalesCTInvoiceTmp.DiscValue1 = this.getMarkupValue(_custInvoiceJour.RecId, metCBCTInvoiceHeaderTable.Number, METChargeType::ChargeThroughDiscCode1);
            metSalesCTInvoiceTmp.Disc1Amt = -1 * abs(metSalesCTInvoiceTmp.VendInvoiceAmtInclGST * metSalesCTInvoiceTmp.DiscValue1/100); //282469 passing value as same sign as in markup setup
            
            metSalesCTInvoiceTmp.DiscValue2 = this.getMarkupValue(_custInvoiceJour.RecId, metCBCTInvoiceHeaderTable.Number, METChargeType::ChargeThroughDiscCode2);
            metSalesCTInvoiceTmp.Disc2Amt = -1 * abs(metSalesCTInvoiceTmp.VendInvoiceAmtInclGST * metSalesCTInvoiceTmp.DiscValue2/100);

            metSalesCTInvoiceTmp.MarginValue = this.getMarkupHeaderValue(_custInvoiceJour, METChargeType::ChargeOnChargethrough);
            metSalesCTInvoiceTmp.MarginAmt = (metSalesCTInvoiceTmp.VendInvoiceAmtInclGST + metSalesCTInvoiceTmp.Disc1Amt + metSalesCTInvoiceTmp.Disc2Amt) * metSalesCTInvoiceTmp.MarginValue/100;
             
            metSalesCTInvoiceTmp.GSTPayable = metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount;//GST

            recList.add(metSalesCTInvoiceTmp);
        }

        recList.insertDatabase();
    }

    /// <summary>
    /// Cb272 Invoicing - VM
    /// Fetch the invoice category value of the product attribute as per requirement
    /// </summary>
    /// <param name = "_itemID">_itemID</param>
    /// <returns>AttributeValueText</returns>
    public AttributeValueText metGetProductAttributeforInvCategory(ItemId _itemID)
    {
        InventTable                 InventTable;
        EcoResProductAttributeValue ecoResProductAttributeValue;
        EcoResAttribute             ecoResAttribute;
        EcoResValue                 ecoResValue;

        select firstonly RecId from InventTable where InventTable.itemid == _itemID
            join RecId,Value from ecoResProductAttributeValue
                where ecoResProductAttributeValue.Product == InventTable.Product
            join Name from ecoResAttribute
                where ecoResProductAttributeValue.Attribute == ecoResAttribute.RecId
                    && ecoResAttribute.Name == METConstants::InvoiceCategory
            join ecoResValue
                where ecoResValue.RecId == ecoResProductAttributeValue.Value;

        return  any2Str(ecoResValue.Value());
    }

    /// <summary>
    /// Cb272 get default dimension 
    /// </summary>
    /// <param name = "_defaultDimension">_defaultDimension</param>
    /// <param name = "_dimName">_dimName</param>
    /// <returns>DimensionValue</returns>
    public container getDimensionDisplayValue(RecId _defaultDimension, Name _dimName)
    {
        DimensionAttributeValueSetStorage dimStorage = DimensionAttributeValueSetStorage::find(_defaultDimension);
        RecId attributeValueRecId = dimStorage.getValueByDimensionAttribute(DimensionAttribute::findByName(_dimName).RecId);
        DimensionAttributeValue attributeValue = DimensionAttributeValue::find(attributeValueRecId);
        DimensionFinancialTag finTag = DimensionFinancialTag::find(0);
        DimensionAttributeDirCategory dimAttributeDirCategory;

        select firstonly finTag
            exists join dimAttributeDirCategory where
                dimAttributeDirCategory.DimensionAttribute == attributeValue.DimensionAttribute &&
                finTag.FinancialTagCategory == dimAttributeDirCategory.DirCategory;

        return [finTag.Value, finTag.Description];
    }

